import{_ as s,a0 as r,w as a,s as i,I as o,x as e,a1 as n,A as p,ao as C}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 CentOS 上启用 软件集 Software Collections（SCL） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 上启用 软件集 Software Collections（SCL） | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 上启用 软件集 Software Collections（SCL） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 上启用 软件集 Software Collections（SCL） | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151215 How to enable Software Collections (SCL) on CentOS","title":"如何在 CentOS 上启用 软件集 Software Collections（SCL）","tag":"201512","desc":""},"relativePath":"201512/20151215 How to enable Software Collections (SCL) on CentOS.md","filePath":"[post].md"}'),d={name:"201512/20151215 How to enable Software Collections (SCL) on CentOS.md"};function S(u,t,L,f,c,m){const l=r("Link");return a(),i("div",null,[t[17]||(t[17]=o("h1",{id:"如何在-centos-上启用-软件集-software-collections-scl",tabindex:"-1"},[e("如何在 CentOS 上启用 软件集 Software Collections（SCL） "),o("a",{class:"header-anchor",href:"#如何在-centos-上启用-软件集-software-collections-scl","aria-label":"Permalink to “如何在 CentOS 上启用 软件集 Software Collections（SCL）”"},"​")],-1)),t[18]||(t[18]=o("p",null,"红帽企业版 linux（RHEL）和它的社区版分支——CentOS，提供10年的生命周期，这意味着 RHEL/CentOS 的每个版本会提供长达10年的安全更新。虽然这么长的生命周期为企业用户提供了迫切需要的系统兼容性和可靠性，但也存在一个缺点：随着底层的 RHEL/CentOS 版本接近生命周期的结束，核心应用和运行时环境变得陈旧过时。例如 CentOS 6.5，它的生命周期结束时间是2020年11月30日，其所携带的 Python 2.6.6和 MySQL 5.1.73，以今天的标准来看已经非常古老了。",-1)),t[19]||(t[19]=o("p",null,"另一方面，在 RHEL/CentOS 上试图手动升级开发工具链和运行时环境存在使系统崩溃的潜在可能，除非所有依赖都被正确解决。通常情况下，手动升级都是不推荐的，除非你知道你在干什么。",-1)),o("p",null,[n(l,{href:"https://www.softwarecollections.org/"},{default:p(()=>[...t[0]||(t[0]=[e("软件集（Software Collections）",-1)])]),_:1}),t[1]||(t[1]=e("（SCL）源出现了，以帮助解决 RHEL/CentOS 下的这种问题。SCL 的创建就是为了给 RHEL/CentOS 用户提供一种以方便、安全地安装和使用应用程序和运行时环境的多个（而且可能是更新的）版本的方式，同时避免把系统搞乱。与之相对的是第三方源，它们可能会在已安装的包之间引起冲突。",-1))]),t[20]||(t[20]=C(`<p>最新的 SCL 提供了：</p><ul><li>Python 3.3 和 2.7</li><li>PHP 5.4</li><li>Node.js 0.10</li><li>Ruby 1.9.3</li><li>Perl 5.16.3</li><li>MariaDB 和 MySQL 5.5</li><li>Apache httpd 2.4.6</li></ul><p>在这篇教程的剩余部分，我会展示一下如何配置 SCL 源，以及如何安装和启用 SCL 中的包。</p><h3 id="配置-scl-源" tabindex="-1">配置 SCL 源 <a class="header-anchor" href="#配置-scl-源" aria-label="Permalink to “配置 SCL 源”">​</a></h3><p>SCL 可用于 CentOS 6.5 及更新的版本。要配置 SCL 源，只需执行：</p><pre><code>$ sudo yum install centos-release-SCL
</code></pre><p>要启用和运行 SCL 中的应用，你还需要安装下列包：</p><pre><code>$ sudo yum install scl-utils-build
</code></pre><p>执行下面的命令可以查看 SCL 中可用包的完整列表：</p><pre><code>$ yum --disablerepo=&quot;*&quot; --enablerepo=&quot;scl&quot; list available
</code></pre><p><img src="https://c2.staticflickr.com/6/5730/23304424250_f5c8a09584_c.jpg" alt=""></p><h3 id="从-scl-中安装和启用包" tabindex="-1">从 SCL 中安装和启用包 <a class="header-anchor" href="#从-scl-中安装和启用包" aria-label="Permalink to “从 SCL 中安装和启用包”">​</a></h3><p>既然你已配置好了 SCL，你可以继续并从 SCL 中安装包了。</p><p>你可以搜索 SCL 中的包：</p><pre><code>$ yum --disablerepo=&quot;*&quot; --enablerepo=&quot;scl&quot; search &lt;keyword&gt;
</code></pre><p>我们假设你要安装 Python 3.3。</p><p>继续，就像通常安装包那样使用 yum 安装：</p><pre><code>$ sudo yum install python33
</code></pre><p>任何时候你都可以查看从 SCL 中安装的包的列表，只需执行：</p><pre><code>$ scl --list

python33
</code></pre><p>SCL 的优点之一是安装其中的包不会覆盖任何系统文件，并且保证不会引起与系统中其它库和应用的冲突。</p><p>例如，如果在安装 python33 包后检查默认的 python 版本，你会发现默认的版本并没有改变：</p><pre><code>$ python --version

Python 2.6.6
</code></pre><p>如果想使用一个已经安装的 SCL 包，你需要在每个命令中使用 <code>scl</code> 命令显式启用它（LCTT 译注：即想在哪条命令中使用 SCL 中的包，就得通过<code>scl</code>命令执行该命令）</p><pre><code>$ scl enable &lt;scl-package-name&gt; &lt;command&gt;
</code></pre><p>例如，要针对<code>python</code>命令启用 python33 包：</p><pre><code>$ scl enable python33 &#39;python --version&#39;

Python 3.3.2
</code></pre><p>如果想在启用 python33 包时执行多条命令，你可以像下面那样创建一个启用 SCL 的 bash 会话：</p><pre><code>$ scl enable python33 bash
</code></pre><p>在这个 bash 会话中，默认的 python 会被切换为3.3版本，直到你输入<code>exit</code>，退出会话。</p><p><img src="https://c2.staticflickr.com/6/5642/23491549632_1d08e163cc_c.jpg" alt=""></p><p>简而言之，SCL 有几分像 Python 的虚拟环境，但更通用，因为你可以为远比 Python 更多的应用启用/禁用 SCL 会话。</p>`,32)),o("p",null,[t[3]||(t[3]=e("更详细的 SCL 指南，参考官方的",-1)),n(l,{href:"https://www.softwarecollections.org/docs/"},{default:p(()=>[...t[2]||(t[2]=[e("快速入门指南",-1)])]),_:1})]),t[21]||(t[21]=o("hr",null,null,-1)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),n(l,{href:"http://xmodulo.com/enable-software-collections-centos.html"},{default:p(()=>[...t[4]||(t[4]=[e("http://xmodulo.com/enable-software-collections-centos.html",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("作者：",-1)),n(l,{href:"http://xmodulo.com/author/nanni"},{default:p(()=>[...t[6]||(t[6]=[e("Dan Nanni",-1)])]),_:1}),t[10]||(t[10]=e(" 译者：",-1)),n(l,{href:"https://github.com/bianjp"},{default:p(()=>[...t[7]||(t[7]=[e("bianjp",-1)])]),_:1}),t[11]||(t[11]=e(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[13]||(t[13]=[e("Linux中国",-1)])]),_:1}),t[16]||(t[16]=e(" 荣誉推出",-1))])])}const h=s(d,[["render",S]]);export{b as __pageData,h as default};
